transaction_bp = Blueprint('transaction', __name__)

@transaction_bp.route('/api/transfer', methods=['POST'])
@token_required
def transfer(current_user):
    data = request.get_json() or {}
    to_user_id = data.get('to_user_id')
    try:
        amount = Decimal(str(data.get('amount', 0)))
    except (InvalidOperation, TypeError):
        return jsonify({'error': 'Invalid amount'}), 400
    if amount <= 0:
        return jsonify({'error': 'Amount must be positive'}), 400
    description = data.get('description', '')

    if to_user_id == current_user.id:
        return jsonify({'error': 'Cannot transfer to self'}), 400

    receiver = User.query.get(to_user_id)
    if not receiver:
        return jsonify({'error': 'Receiver not found'}), 404

    # lock rows; check balance before mutate
    sender = User.query.with_for_update().get(current_user.id)
    receiver = User.query.with_for_update().get(receiver.id)
    if sender.balance < amount:
        return jsonify({'error': 'Insufficient balance'}), 400

    sender.balance -= amount
    receiver.balance += amount
    transaction = Transaction(
        sender_id=sender.id,
        receiver_id=receiver.id,
        amount=amount,
        description=description,
        status='completed',
        completed_at=datetime.utcnow()
    )
    db.session.add(transaction)
    db.session.commit()

    return jsonify({
        'message': 'Transfer successful',
        'transaction': transaction.to_dict()
    })

